        return 150000;
    }
}

class CarTyre implements Tyre {

    public String spec() {
        return "4 x radial 15 inch";
    }

    public int cost() {
        return 24000;
    }
}

class CarBody implements Body {

    public String spec() {
        return "steel monocoque";
    }

