        return 200000;
    }
}

class BikeEngine implements Engine {

    public String spec() {
        return "125cc single cylinder";
    }

    public int cost() {
        return 20000;
    }
}

class BikeTyre implements Tyre {

    public String spec() {
        return "2 x tubeless 17 inch";
    }

    public int cost() {
        return 3500;
    }
}

class BikeBody implements Body {

    public String spec() {
        return "tubular frame";
    }

    public int cost() {
        return 12000;
    }
