// CompositeOrgChartDemo - parent links and a flattening stream
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

public class CompositeOrgChartDemo {
    public static void main(String[] args) {
        Employee intern = new Employee("Tara", "Intern", 3);
        Employee lead = new Employee("Rohit", "Team Lead", 24)
                .add(new Employee("Sana", "Developer", 14))
                .add(intern);
        Employee ceo = new Employee("Usha", "CEO", 90)
                .add(lead)
                .add(new Employee("Dilip", "CFO", 60));

        System.out.println("Everyone: " + ceo.stream().map(Employee::label).toList());
        System.out.println("Cost of Rohit's team: " + lead.teamCost() + " lakh");
        System.out.println("Cost of company: " + ceo.teamCost() + " lakh");
        System.out.println("Chain: " + intern.chainOfCommand());
    }
}

class Employee {
    private final String name;
    private final String title;
    private final int salaryLakh;
    private Employee boss;
    private final List<Employee> reports = new ArrayList<>();

    Employee(String name, String title, int salaryLakh) {
        this.name = name;
        this.title = title;
        this.salaryLakh = salaryLakh;
    }

    Employee add(Employee e) {
        e.boss = this; // set the parent link
        reports.add(e);
        return this;
    }

    // Flatten this node and all descendants
    Stream<Employee> stream() {
        return Stream.concat(Stream.of(this), reports.stream().flatMap(Employee::stream));
    }

    int teamCost() {
        return stream().mapToInt(e -> e.salaryLakh).sum();
    }

    String chainOfCommand() {
        return boss == null ? name : name + " -> " + boss.chainOfCommand();
    }

    String label() {
        return name + " (" + title + ")";
    }
}
// OUTPUT:
// Everyone: [Usha (CEO), Rohit (Team Lead), Sana (Developer), Tara (Intern), Dilip (CFO)]
// Cost of Rohit's team: 41 lakh
// Cost of company: 191 lakh
// Chain: Tara -> Rohit -> Usha

package com.javaschoollab.demo;

import java.util.HashMap;
import java.util.Map;

// Flyweight - stores only shared (intrinsic) state
class CharacterStyle {
    private final String font; // intrinsic - shared across many characters

    public CharacterStyle(String font) {
        this.font = font;
        System.out.println("Creating NEW style object for font: " + font);
    }

    // position is extrinsic - passed in, not stored here
    public void render(char c, int position) {
        System.out.println("Rendering '" + c + "' at position " + position + " using font " + font);
    }
}

// Factory - ensures each distinct font only creates ONE shared flyweight
class CharacterStyleFactory {
    private static final Map<String, CharacterStyle> cache = new HashMap<>();

    public static CharacterStyle getStyle(String font) {
        return cache.computeIfAbsent(font, CharacterStyle::new);
    }
}

public class FlyweightDemo {
    public static void main(String[] args) {
        CharacterStyle style1 = CharacterStyleFactory.getStyle("Arial");
        style1.render('H', 0);

        CharacterStyle style2 = CharacterStyleFactory.getStyle("Arial"); // reuses the SAME object
        style2.render('i', 1);

        System.out.println("Same shared object? " + (style1 == style2));
    }
}
// OUTPUT:
// Creating NEW style object for font: Arial
// Rendering 'H' at position 0 using font Arial
// Rendering 'i' at position 1 using font Arial
// Same shared object? true

