public class StLambdaDiscountDemo {
    public static void main(String[] args) {
        StCheckout checkout = new StCheckout();
        String[] codes = {"NONE", "FESTIVE10", "FLAT200", "STUDENT", "UNKNOWN"};

        for (String code : codes) {
